{
  "name": "@renjfk/opencode-secret-tools",
  "version": "1.0.0",
  "description": "Configurable secret bridge for OpenCode. Provides list_secrets, get_secret, and clear_secret tools that shell out to any CLI-based secret store with automatic redaction.",
  "keywords": [
    "opencode",
    "plugin",
    "redaction",
    "secret",
    "vault"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/renjfk/opencode-secret-tools.git"
  },
  "files": [
    "index.js",
    "lib",
    "screenshots"
  ],
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": {
      "import": "./index.js"
    }
  },
  "scripts": {
    "lint": "npx oxlint .",
    "fmt": "npx oxfmt --check .",
    "fmt:fix": "npx oxfmt --write .",
    "test": "node --test",
    "check": "npm run lint && npm run fmt",
    "prepack": "npm run check"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.2.1",
    "oxfmt": "0.50.0",
    "oxlint": "1.65.0"
  }
}

import { Plugin } from "@opencode/plugin";
import { createRedactor } from "./lib/redact.js";
import { expandGetCmd, parseListOutput, runCommand } from "./lib/vault.js";

// ---------------------------------------------------------------------------
// Permission + result helpers
// ---------------------------------------------------------------------------

// V2 only blocks a tool when its rule is a whole-tool deny on "*"; prompting
// for anything else is the tool's own job. Asserting here makes ask rules and
// resource-scoped rules enforceable again.
function assertPermission(ctx, context, action, resources, save, metadata) {
  if (!context?.sessionID) return Promise.resolve();
  return ctx.permission.assert({
    sessionID: context.sessionID,
    agent: context.agent,
    action,
    resources,
    ...(save?.length ? { save } : {}),
    ...(metadata ? { metadata } : {}),
    source: { type: "tool", messageID: context.messageID, id: context.id },
  });
}

function redactResult(redactor, result) {
  if (!result) return;
  if (typeof result.content === "string") {
    result.content = redactor.redact(result.content);
  } else if (Array.isArray(result.content)) {
    result.content = result.content.map((item) =>
      item && item.type === "text" && typeof item.text === "string"
        ? { ...item, text: redactor.redact(item.text) }
        : item,
    );
  }
  if (result.metadata) {
    result.metadata = JSON.parse(redactor.redact(JSON.stringify(result.metadata)));
  }
}

// ---------------------------------------------------------------------------
// Plugin
// ---------------------------------------------------------------------------

export default Plugin.define({
  id: "secret-tools",
  async setup(ctx) {
    const options = ctx.options || {};
    const folder = options.folder || "";
    const listCmd = options.listCmd;
    const getCmd = options.getCmd;

    if (!listCmd || !getCmd) {
      throw new Error("Both listCmd and getCmd are required options");
    }

    // Per-instance state: setup runs once per location, so a secret loaded in
    // one project is redacted and injected there only. npm installs evaluate
    // the module once per process, so module-level state would leak secrets
    // across projects through every instance's shell hook. Secrets are also
    // deliberately NOT written to process.env: that would leak them into
    // other projects' sessions on the shared V2 server, and main-session
    // shells do not inherit the server environment anyway (they run with the
    // TUI terminal's environment, so a process.env write never reached them).
    const redactor = createRedactor();
    const loadedSecrets = {};

    // Injects loaded secrets into every shell command this process runs for
    // the plugin's sessions, replacing the old process.env write: main-session
    // shells get the values, and other projects' sessions never do.
    await ctx.shell.hook("create.before", async (event) => {
      for (const [name, value] of Object.entries(loadedSecrets)) {
        event.env[name] = value;
      }
    });

    await ctx.tool.transform((editor) => {
      editor.add({
        name: "list_secrets",
        description: "List available secret names from the vault.",
        input: {
          type: "object",
          properties: {},
          additionalProperties: false,
        },
        options: { codemode: false },
        execute: async (input, context) => {
          await assertPermission(ctx, context, "list_secrets", [folder || "*"], [], {
            folder: folder || "(all)",
          });

          const raw = await runCommand(listCmd[0], listCmd.slice(1));
          const names = parseListOutput(raw, folder);
          const content = names.length
            ? names.map((n) => `- ${n}`).join("\n") + "\n"
            : `No secrets found${folder ? ` in folder ${folder}` : ""}.\n`;

          return { content, metadata: { count: names.length, folder: folder || "(all)" } };
        },
      });

      editor.add({
        name: "get_secret",
        description:
          "Read one secret value by exact name from the vault and load it for shell commands. Returns a confirmation. Use the secret in subsequent bash commands via $NAME. WARNING: Never expose the value of this secret in chat responses or tool outputs visible to the user.",
        input: {
          type: "object",
          properties: {
            name: {
              type: "string",
              description: "Exact secret item name in the vault",
            },
          },
          required: ["name"],
          additionalProperties: false,
        },
        options: { codemode: false },
        execute: async (input, context) => {
          const name = String(input.name ?? "").trim();
          if (!name) throw new Error("name is required");

          await assertPermission(ctx, context, "get_secret", [name], [name], {
            name,
            folder: folder || "(all)",
          });

          const expanded = expandGetCmd(getCmd, name);
          const value = await runCommand(expanded[0], expanded.slice(1));
          const trimmed = value.trimEnd();
          if (!trimmed) throw new Error(`Secret has no readable value: ${name}`);

          loadedSecrets[name] = trimmed;
          redactor.track(name, trimmed);

          return {
            content: `${name} loaded. Use via $${name} in shell commands.`,
            metadata: { name, folder: folder || "(all)" },
          };
        },
      });

      editor.add({
        name: "clear_secret",
        description:
          "Stop injecting a secret into shell commands. Call after you are done using the secret.",
        input: {
          type: "object",
          properties: {
            name: {
              type: "string",
              description: "Exact secret name to clear",
            },
          },
          required: ["name"],
          additionalProperties: false,
        },
        options: { codemode: false },
        execute: async (input) => {
          const name = String(input.name ?? "").trim();
          if (!name) throw new Error("name is required");

          if (name in loadedSecrets) {
            delete loadedSecrets[name];
            redactor.clear(name);
            return {
              content: `${name} is no longer injected into shell commands.`,
              metadata: { name },
            };
          }
          return { content: `${name} was not loaded.`, metadata: { name } };
        },
      });
    });

    await ctx.tool.hook("execute.after", async (event) => {
      if (event.status !== "completed" || !event.result) return;

      const result = event.result;
      const name = String(event.input?.name ?? "").trim();

      if (event.tool === "list_secrets") {
        result.metadata = { ...result.metadata, title: "List secrets" };
        return;
      }

      if (event.tool === "get_secret") {
        result.metadata = {
          ...result.metadata,
          title: name ? `Read secret ${name}` : "Read secret",
        };
      }

      if (event.tool === "clear_secret") {
        result.metadata = {
          ...result.metadata,
          title: name ? `Clear secret ${name}` : "Clear secret",
        };
      }

      redactResult(redactor, result);
    });
  },
});
